<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\OAuth\Client\Domain;

/**
 * Immutable snapshot of a tenant's dynamic client registration rules (tasks 023 and 024), read
 * from its TenantConfig: whether registration is open, gated behind an initial access token or
 * disabled, and which grant types and token endpoint auth methods a registered client may get.
 *
 * The password grant is only granted when it is listed and the tenant also allows it explicitly,
 * so that ROPC is never obtained through DCR by default.
 */
final class DcrRegistrationRules
{
    public const string OPEN = 'open';
    public const string TOKEN_REQUIRED = 'token-required';
    public const string DISABLED = 'disabled';

    public function __construct(
        /** One of OPEN, TOKEN_REQUIRED or DISABLED. */
        public readonly string $policy,
        /** @var string[] Grant types a dynamically registered client may request. */
        public readonly array $allowedGrantTypes,
        /** @var string[] Token endpoint auth methods a dynamically registered client may use. */
        public readonly array $allowedAuthMethods,
        /** Explicit tenant permission for the password grant (ROPC). */
        public readonly bool $allowPasswordGrant = false,
    ) {
    }

    /**
     * The rules of a tenant without configuration: no registration at all.
     */
    public static function disabled(): self
    {
        return new self(self::DISABLED, [], []);
    }

    /**
     * The same rules with the grant types of an initial access token, which take precedence over
     * the tenant ones when the token defines them.
     *
     * @param string[]|null $grantTypes
     */
    public function withGrantTypes(?array $grantTypes): self
    {
        return $grantTypes === null
            ? $this
            : new self($this->policy, $grantTypes, $this->allowedAuthMethods, $this->allowPasswordGrant);
    }
}
